import{_ as a,o as s,c as i,an as e}from"./chunks/framework.BR9x3YLT.js";const k=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"getting_started/installation.md","filePath":"getting_started/installation.md","lastUpdated":null}'),n={name:"getting_started/installation.md"};function l(o,t,r,h,p,d){return s(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="Installation" tabindex="-1">Installation <a class="header-anchor" href="#Installation" aria-label="Permalink to &quot;Installation {#Installation}&quot;">​</a></h1><p>This guide installs AtmosTransport from source and verifies that Julia can load it. The first simulation on the next page uses the CPU and synthetic data, so you do not need a GPU, meteorological credentials, Python, or NetCDF command-line tools.</p><h2 id="1.-Install-Julia-and-Git" tabindex="-1">1. Install Julia and Git <a class="header-anchor" href="#1.-Install-Julia-and-Git" aria-label="Permalink to &quot;1. Install Julia and Git {#1.-Install-Julia-and-Git}&quot;">​</a></h2><p>AtmosTransport requires Julia 1.10 or later. Install Julia with <a href="https://github.com/JuliaLang/juliaup" target="_blank" rel="noreferrer">juliaup</a>, the installer recommended by the Julia project, then open a new terminal and check the version:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>Any result beginning with <code>julia version 1.10</code> or newer is suitable. You also need <a href="https://git-scm.com/downloads" target="_blank" rel="noreferrer">Git</a>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">New to terminals or Julia?</p><p>Read <a href="/AtmosTransport.jl/v0.3/getting_started/julia_basics#Julia-orientation">Julia orientation</a> for the difference between terminal commands, the <code>julia&gt;</code> prompt, and Julia&#39;s <code>pkg&gt;</code> prompt. You can return here after the two-minute overview.</p></div><h2 id="2.-Clone-the-repository" tabindex="-1">2. Clone the repository <a class="header-anchor" href="#2.-Clone-the-repository" aria-label="Permalink to &quot;2. Clone the repository {#2.-Clone-the-repository}&quot;">​</a></h2><p>AtmosTransport is not installed from Julia&#39;s General registry yet. Clone the source and enter the repository directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/RemoteSensingTools/AtmosTransport.jl.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> AtmosTransport.jl</span></span></code></pre></div><p>All commands in this documentation assume that your terminal remains in this directory. A quick check is:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Project.toml</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;repository root found&quot;</span></span></code></pre></div><p>On Windows PowerShell, use <code>Test-Path Project.toml</code> instead.</p><h2 id="3.-Install-the-Julia-environment" tabindex="-1">3. Install the Julia environment <a class="header-anchor" href="#3.-Install-the-Julia-environment" aria-label="Permalink to &quot;3. Install the Julia environment {#3.-Install-the-Julia-environment}&quot;">​</a></h2><p>Instantiate the packages declared by <code>Project.toml</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.instantiate()&#39;</span></span></code></pre></div><p>The first run downloads packages and precompiles them. It can take several minutes and may appear quiet for short periods. Later starts reuse the compiled cache.</p><h2 id="4.-Verify-the-package-loads" tabindex="-1">4. Verify the package loads <a class="header-anchor" href="#4.-Verify-the-package-loads" aria-label="Permalink to &quot;4. Verify the package loads {#4.-Verify-the-package-loads}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using AtmosTransport; println(&quot;AtmosTransport is ready&quot;)&#39;</span></span></code></pre></div><p>Expected final line:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AtmosTransport is ready</span></span></code></pre></div><p>That is enough to continue. The <a href="/AtmosTransport.jl/v0.3/getting_started/quickstart#Quickstart">Quickstart</a> performs a more useful end-to-end check by creating a current transport binary, running the model, and writing NetCDF output.</p><h2 id="Optional:-run-the-regression-suite" tabindex="-1">Optional: run the regression suite <a class="header-anchor" href="#Optional:-run-the-regression-suite" aria-label="Permalink to &quot;Optional: run the regression suite {#Optional:-run-the-regression-suite}&quot;">​</a></h2><p>The complete synthetic CPU suite is intended for contributors and takes much longer than the load check:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.test()&#39;</span></span></code></pre></div><p>It requires no private meteorological data. Real-data and large diagnostic campaigns are separate opt-in test tiers.</p><h2 id="Optional:-GPU-support" tabindex="-1">Optional: GPU support <a class="header-anchor" href="#Optional:-GPU-support" aria-label="Permalink to &quot;Optional: GPU support {#Optional:-GPU-support}&quot;">​</a></h2><p>Start on the CPU. Once the quickstart works, a run can request an available backend through TOML:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">architecture</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">use_gpu = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backend = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;auto&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # or &quot;cuda&quot; / &quot;metal&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">numerics</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">float_type = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Float32&quot;</span></span></code></pre></div><ul><li><p>NVIDIA runs use CUDA. <code>Float32</code> is the practical production default on most GPUs; <code>Float64</code> is supported where hardware performance permits.</p></li><li><p>Apple Silicon runs use Metal and require <code>Float32</code>.</p></li><li><p>The runtime fails clearly if a requested GPU backend is unavailable; it does not silently change the execution path to CPU.</p></li></ul><p>Backend packages are optional weak dependencies, so a fresh CPU installation does not fetch them. Add only the backend you need to your Julia user environment:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.add(&quot;CUDA&quot;)&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # NVIDIA</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.add(&quot;Metal&quot;)&#39;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Apple Silicon</span></span></code></pre></div><p>Then diagnose it after the base installation succeeds:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using CUDA; CUDA.versioninfo()&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Metal; Metal.versioninfo()&#39;</span></span></code></pre></div><p>Run only the command appropriate for your hardware.</p><h2 id="Troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#Troubleshooting" aria-label="Permalink to &quot;Troubleshooting {#Troubleshooting}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Symptom</th><th style="text-align:right;">Fix</th></tr></thead><tbody><tr><td style="text-align:right;"><code>julia: command not found</code></td><td style="text-align:right;">Open a new terminal after installing Julia, or finish the juliaup PATH setup.</td></tr><tr><td style="text-align:right;"><code>Package AtmosTransport not found</code></td><td style="text-align:right;">Run from the cloned repository and include <code>--project=.</code>.</td></tr><tr><td style="text-align:right;">A dependency “does not seem to be installed”</td><td style="text-align:right;">Re-run <code>julia --project=. -e &#39;using Pkg; Pkg.instantiate()&#39;</code>.</td></tr><tr><td style="text-align:right;">Julia loads the wrong checkout</td><td style="text-align:right;">Run <code>Base.active_project()</code> in the REPL; it should end in this repository&#39;s <code>Project.toml</code>.</td></tr><tr><td style="text-align:right;">GPU package fails to load</td><td style="text-align:right;">Keep <code>[architecture].use_gpu = false</code> and finish the CPU quickstart before debugging drivers.</td></tr></tbody></table><h2 id="Next-step" tabindex="-1">Next step <a class="header-anchor" href="#Next-step" aria-label="Permalink to &quot;Next step {#Next-step}&quot;">​</a></h2><p>Run the <a href="/AtmosTransport.jl/v0.3/getting_started/quickstart#Quickstart">Quickstart</a>. If the syntax is unfamiliar, keep the <a href="/AtmosTransport.jl/v0.3/getting_started/julia_basics#Julia-orientation">Julia orientation</a> page open alongside it.</p>`,40)])])}const u=a(n,[["render",l]]);export{k as __pageData,u as default};
